GEO_NAME_RE = re.compile(r"^[\w .,'()\-]{2,48}$", re.UNICODE)


def get_geo_country(name: str, region: str | None = None) -> dict:
    query = GEO_SEARCH.get(name) or f'"{name}"'

    def load():
        items = google_news(query + " when:4d", 40)
        now = time.time() * 1000
        heads, score, themes, esc, deesc = [], 0.0, defaultdict(int), 0, 0
        for it in items:
            tag = geo_tag(it["title"])
            age_h = max(0.0, (now - (it.get("ts") or now)) / 3.6e6)
            w = sorted((GEO_THEMES[t][1] for t in tag["themes"]), reverse=True)
            base = (w[0] + 0.35 * sum(w[1:])) if w else 0.35          # general news counts a little
            mult = 1.5 if tag["esc"] else 0.7 if tag["deesc"] else 1.0
            sc = base * mult * math.exp(-age_h / 48)
            score += sc
            esc += tag["esc"]
            deesc += tag["deesc"]
            for t in tag["themes"]:
                themes[t] += 1
            heads.append({"title": it["title"], "url": it["url"], "site": it.get("site"), "ts": it.get("ts"), "score": round(sc, 3), **tag})
        risk = 100 * (1 - math.exp(-score / 9))
        lvl = "SEVERE" if risk >= 75 else "HIGH" if risk >= 50 else "ELEVATED" if risk >= 25 else "LOW"
        top = sorted(themes.items(), key=lambda kv: -kv[1] * GEO_THEMES[kv[0]][1])
        assets = list(dict.fromkeys((GEO_ASSETS.get(name) or []) + [a for t, _ in top[:2] for a in GEO_THEME_ASSETS.get(t, [])] + GEO_REGION_ASSETS.get(region or "", [])))[:6]
        return {"key": name, "name": name, "query": query, "risk": round(risk, 1), "level": lvl, "n": len(heads), "themes": dict(themes), "topTheme": top[0][0] if top else None,
                "esc": esc, "deesc": deesc, "headlines": heads, "assets": assets, "asof": int(now), "source": "Google News"}
    return cached(f"geoc:{name}", 900, load, keep_empty_for=180)


@app.get("/api/geo/country")
def api_geo_country(name: str = Query(..., min_length=2, max_length=48), region: str = ""):
    if not GEO_NAME_RE.match(name):
        raise HTTPException(400, "Unknown country name.")
    return guard(lambda: get_geo_country(name, region if region in GEO_REGION_ASSETS else None))

@app.get("/api/perf")
def api_perf(symbols: str):
    syms = syms_ok(symbols, 80)
    if not syms:
        raise HTTPException(400, "No valid symbols.")
    return {"perf": guard(lambda: get_perf(syms))}


@app.get("/api/earnings")
def api_earnings():
    return guard(get_earnings)


@app.get("/api/geo")
def api_geo():
    return guard(lambda: cached("geo", 600, get_geo, keep_empty_for=120))


# ------------------------------------------------------------------ trading bot API
async def _json_body(request: Request, limit: int = 2_000_000) -> dict:
    raw = await request.body()
    if len(raw) > limit:
        raise HTTPException(413, "Request too large.")
    try:
        body = json.loads(raw or b"{}")
    except ValueError:
        raise HTTPException(400, "Body must be JSON.")
    if not isinstance(body, dict):
        raise HTTPException(400, "Body must be a JSON object.")
    return body


@app.get("/api/bot/strategies")
def api_bot_strategies():
    return {"strategies": STRATEGIES, "timeframes": BOT_TFS, "protected": bool(BOT_TOKEN), "tick": BOT_TICK, "max": BOT_MAX}


@app.post("/api/bot/backtest")
async def api_bot_backtest(request: Request):
    body = await _json_body(request)
    return await asyncio.to_thread(lambda: guard(lambda: backtest_request(body)))


@app.post("/api/bot/sweep")
async def api_bot_sweep(request: Request):
    body = await _json_body(request)
    return await asyncio.to_thread(lambda: guard(lambda: sweep_request(body)))


@app.get("/api/bot/list")
def api_bot_list():
    with _BOT_LOCK:
        bots = [bot_public(b) for b in sorted(_BOTS.values(), key=lambda x: x["created"])]
    eng = dict(_BOT_ENGINE)
    eng.update({"tick": BOT_TICK, "protected": bool(BOT_TOKEN), "dataDir": str(BOT_DIR), "persistent": bool(os.environ.get("AGULA_DATA_DIR")), "sessionOpen": _us_session_open()})
    return {"bots": bots, "engine": eng, "asof": _now_ms()}


@app.get("/api/bot/events")
def api_bot_events(since: int = 0):
    return {"events": [e for e in list(_BOT_EVENTS) if e["t"] > since][-50:], "asof": _now_ms()}


@app.get("/api/bot/export")
def api_bot_export():
    with _BOT_LOCK:
        return {"version": 1, "exported": _now_ms(), "bots": json.loads(json.dumps(list(_BOTS.values()), default=str))}


@app.get("/api/bot/{bid}")
def api_bot_get(bid: str):
    with _BOT_LOCK:
        b = _BOTS.get(bid)
        if not b:
            raise HTTPException(404, "No such bot. It may have been deleted, or the server restarted without saved data.")
        return bot_public(b, full=True)


@app.post("/api/bot")
async def api_bot_create(request: Request):
    bot_auth(request)
    body = await _json_body(request)
    b = await asyncio.to_thread(lambda: guard(lambda: bot_new(body)))
    return bot_public(b, full=True)


@app.post("/api/bot/import")
async def api_bot_import(request: Request):
    bot_auth(request)
    body = await _json_body(request, 8_000_000)
    bots = body.get("bots")
    if not isinstance(bots, list):
        raise HTTPException(400, "Expected {\"bots\": [...]} from an Agula bot export.")
    added = 0
    with _BOT_LOCK:
        for b in bots[:BOT_MAX]:
            if not isinstance(b, dict) or not {"id", "symbol", "strategy", "cash", "qty", "capital"} <= set(b):
                continue
            if b["strategy"] not in STRATEGIES or b["id"] in _BOTS or len(_BOTS) >= BOT_MAX:
                continue
            try:
                sym_ok(str(b["symbol"]))
                b["params"] = _strategy_params(b["strategy"], b.get("params"))
            except HTTPException:
                continue
            b.setdefault("status", "stopped")
            if b["status"] not in ("running", "stopped", "paused", "halted"):
                b["status"] = "stopped"
            _bot_log(b, "Imported into this server.")
            _BOTS[b["id"]] = b
            added += 1
    _bot_save()
    return {"added": added}


@app.post("/api/bot/kill")
def api_bot_kill(request: Request):
    """Kill switch: stop every bot and flatten every position at the last price."""
    bot_auth(request)
    n = 0
    with _BOT_LOCK:
        for b in _BOTS.values():
            if b["qty"] and b.get("lastPx"):
                _bot_go(b, 0.0, b["lastPx"], "kill switch")
            if b["status"] != "stopped":
                n += 1
            b["status"] = "stopped"
            _bot_log(b, "Kill switch: stopped and flattened.", "risk")
    _bot_save()
    return {"stopped": n}


@app.post("/api/bot/{bid}/{action}")
async def api_bot_action(bid: str, action: str, request: Request):
    bot_auth(request)
    body = await _json_body(request)
    with _BOT_LOCK:
        b = _BOTS.get(bid)
    if not b:
        raise HTTPException(404, "No such bot.")
    if action == "order":                                  # manual ticket, filled at the live price
        side = str(body.get("side") or "").upper()
        q = (await asyncio.to_thread(lambda: get_quotes([b["symbol"]]))).get(b["symbol"])
        if not q:
            raise HTTPException(502, f"No live quote for {b['symbol']} right now, so the order can't be filled.")
        px = float(q["last"])
        with _BOT_LOCK:
            b["lastPx"] = px
            if side == "FLAT":
                if not b["qty"]:
                    raise HTTPException(400, "Already flat.")
                _bot_go(b, 0.0, px, "manual")
            elif side in ("BUY", "SELL"):
                direction = 1.0 if side == "BUY" else -1.0
                try:
                    qty = float(body.get("qty") or 0)
                    pct = float(body.get("pct") or 0)
                except (TypeError, ValueError):
                    raise HTTPException(400, "Quantity must be a number.")
                if pct:
                    qty = _bot_equity(b, px) * pct / 100 / px
                if qty <= 0:
                    raise HTTPException(400, "Enter a quantity or a % of equity.")
                new = b["qty"] + direction * qty
                if new < -1e-9 and not b.get("allow_short"):
                    raise HTTPException(400, "Shorting is off for this bot. Turn on 'Allow shorts' in its settings, or sell no more than you hold.")
                if abs(new) * px > _bot_equity(b, px) * 1.0001 + 1e-6:
                    raise HTTPException(400, "Paper accounts can't use leverage: that order would exceed the account's equity.")
                _bot_fill(b, direction, px, "manual", qty)
            else:
                raise HTTPException(400, "side must be BUY, SELL or FLAT.")
            b["equityHist"].append([_now_ms(), round(_bot_equity(b, px), 4), round(px, 6)])
    elif action in ("start", "stop", "reset", "delete", "update"):
        with _BOT_LOCK:
            if action == "start":
                b["status"], b["haltReason"], b["waitFlip"] = "running", None, 0.0
                b["peakEq"] = _bot_equity(b)
                _bot_log(b, "Started.")
            elif action == "stop":
                if body.get("flatten") and b["qty"] and b.get("lastPx"):
                    _bot_go(b, 0.0, b["lastPx"], "stopped")
                b["status"] = "stopped"
                _bot_log(b, "Stopped" + (" and flattened." if body.get("flatten") else "; position kept."))
            elif action == "reset":
                now = _now_ms()
                b.update({"cash": b["capital"], "qty": 0.0, "entryPx": None, "entryT": None, "orders": [], "equityHist": [[now, b["capital"], None]],
                          "peakEq": b["capital"], "day": None, "haltReason": None, "waitFlip": 0.0, "lastBarT": None, "status": "stopped", "log": []})
                _bot_log(b, "Reset to starting capital.")
            elif action == "delete":
                _BOTS.pop(bid, None)
            elif action == "update":
                risk = _risk_cfg({**{k: b.get(k) for k in ("size_pct", "fee_bps", "slip_bps", "stop_pct", "take_pct", "trail_pct", "daily_loss_pct", "max_dd_pct", "allow_short")},
                                  "capital": b["capital"], **(body.get("risk") or {})})
                for k in ("size_pct", "fee_bps", "slip_bps", "stop_pct", "take_pct", "trail_pct", "daily_loss_pct", "max_dd_pct", "allow_short"):
                    b[k] = risk[k]
                if "session_only" in body:
                    b["session_only"] = bool(body["session_only"])
                if body.get("name"):
                    b["name"] = re.sub(r"[^\w .+\-/&()]", "", str(body["name"]))[:48] or b["name"]
                _bot_log(b, "Settings updated.")
    else:
        raise HTTPException(404, "Unknown bot action.")
    _bot_save()
    if action == "delete":
        return {"deleted": bid}
    with _BOT_LOCK:
        return bot_public(b, full=True)


# =============================================================================
# Background warming (always-on hosts): keeps first visits fast
# =============================================================================
def _warm_loop():
    time.sleep(2)
    while True:
        t0 = time.time()
        for name, fn in (("curve", get_curve), ("macro", get_macro), ("calendar", get_calendar), ("universe", get_universe), ("news", get_headlines), ("damodaran", get_damodaran),
                         ("quotes", lambda: get_quotes(SECTOR_ETFS + [BENCH, "^VIX", "^TNX", "DX-Y.NYB", "CL=F", "GC=F", "BTC-USD"]))):
            try:
                fn()
            except Exception as exc:
                log.info("warm %s failed: %s", name, exc)
        log.info("warm cycle done in %.1fs", time.time() - t0)
        time.sleep(int(os.environ.get("AGULA_WARM_INTERVAL", "1500")))


